/**
 * login-redirect.ts — redirect to the Databricks auth dialog.
 *
 * This page lives on the SAME domain as the task pane (the static host).
 * Office's displayDialogAsync requires the first dialog page to be
 * same-domain. Once loaded, it immediately redirects to the Databricks
 * App's auth-dialog page, where SSO and token fetching complete.
 */

import { DATABRICKS_APP_URL } from "../../shared/constants";

(function (): void {
  // Compute the relay URL relative to this page so it works on any host
  // (localhost:3000 in dev, reneholt.github.io/office-add-in-ai-assistant
  // in production). The auth-dialog page on Databricks will redirect back
  // to this relay URL after fetching the token.
  var relayUrl = new URL("dialog-relay.html", window.location.href).href;
  var databricksUrl = DATABRICKS_APP_URL + "/auth-dialog.html?relayUrl=" + encodeURIComponent(relayUrl);
  window.location.replace(databricksUrl);
})();
